WITH valid_accounts AS (SELECT * FROM accounts WHERE opened_date < '2024-03-01'), agg AS (SELECT CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 22000 THEN 'mid' ELSE 'low' END AS balance_bucket, SUM(CASE WHEN status = 'CLOSED' THEN balance ELSE 0 END) AS closed_balance FROM valid_accounts GROUP BY CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 22000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, closed_balance FROM agg WHERE closed_balance < 57
